const player = {
  w: 20,
  h: 20,
  x: 50,
  y: HEIGHT - PLATFORM_HEIGHT - 20,
  vy: 0,
  onGround: false,
  draw() {
    const grad = ctx.createRadialGradient(this.x + this.w/2, this.y + this.h/2, 2, this.x + this.w/2, this.y + this.h/2, this.w);
    grad.addColorStop(0, '#ff0');
    grad.addColorStop(1, '#ff8c00');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(this.x + this.w/2, this.y + this.h/2, this.w/2, 0, Math.PI * 2);
    ctx.fill();
  },
  update() {
    this.vy += GRAVITY;
    this.y += this.vy;
    // simple ground check
    if (this.y + this.h >= HEIGHT - PLATFORM_HEIGHT) {
      this.y = HEIGHT - PLATFORM_HEIGHT - this.h;
      this.vy = 0;
      this.onGround = true;
    } else {
      this.onGround = false;
    }
  },
  jump() {
    if (this.onGround) this.vy = JUMP_STRENGTH;
  },
};

